-- Uniques (wowproject docs/uniques-draft.md): hand-authored named items, quality 6 (light gold), fixed stats on a
-- base item's look, dropped only by their creature. Data: 2026_10_14_01_item_unique_data.sql (generated by
-- wowproject tools/loot-analysis/uniques_sql.py from uniques.json).
CREATE TABLE IF NOT EXISTS `item_unique` (
  `key` VARCHAR(30) NOT NULL,
  `name` VARCHAR(80) NOT NULL,
  `base_entry` INT UNSIGNED NOT NULL,
  `item_level` TINYINT UNSIGNED NOT NULL,
  `required_level` TINYINT UNSIGNED NOT NULL,
  `description` VARCHAR(200) NOT NULL DEFAULT '',
  `creature_entry` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'drops only from this creature (0: none)',
  `chance` FLOAT NOT NULL DEFAULT 1 COMMENT '% per kill',
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `item_unique_stat` (
  `unique_key` VARCHAR(30) NOT NULL,
  `idx` TINYINT UNSIGNED NOT NULL,
  `effect` TINYINT UNSIGNED NOT NULL COMMENT 'ItemAffixEffect: 0 stat, 1 flat armor, 5 resistance',
  `effect_arg` INT NOT NULL COMMENT 'ItemModType for stats, SpellSchools for resistances',
  `value` INT NOT NULL,
  PRIMARY KEY (`unique_key`, `idx`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
